%   returns ki: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    kp = zeros(3, 1);
    kd = zeros(3, 1);
    ki = zeros(3, 1);
    kp = zeros(3, 1);
    kd = zeros(3, 1);
    ki = zeros(3, 1);
    for ax = (0):((3) - 1)
        kp((ax) + 1) = ((ii((ax) + 1) * wn) * wn);
        kd((ax) + 1) = (((2 * z) * ii((ax) + 1)) * wn);
    end
end
